const response = $input.first()?.json ?? {};
const products = Array.isArray(response.data) ? response.data : [];
const escapeHtml = (value) => String(value ?? '').replace(/[&<>\"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', "'": '&#39;' })[character]);
const money = new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN' });
const rows = products.map((product) => `<tr><td>${escapeHtml(product.name)}</td><td>${escapeHtml(product.category)}</td><td>${money.format(Number(product.price))}</td><td>${Number(product.stock)}</td></tr>`).join('');
const table = products.length ? `<table style="border-collapse:collapse;width:100%"><thead><tr><th style="text-align:left;border-bottom:1px solid #ccc;padding:8px">Producto</th><th style="text-align:left;border-bottom:1px solid #ccc;padding:8px">Categoría</th><th style="text-align:left;border-bottom:1px solid #ccc;padding:8px">Precio</th><th style="text-align:left;border-bottom:1px solid #ccc;padding:8px">Existencias</th></tr></thead><tbody>${rows}</tbody></table>` : '<p>La API no devolvió productos.</p>';
return [{ json: { subject: `Catálogo de productos (${products.length})`, html: `<div style="font-family:Arial,sans-serif"><h2>Catálogo de productos</h2><p>Se encontraron ${products.length} productos en la API.</p>${table}<p>Correo generado automáticamente desde n8n.</p></div>`, count: products.length } }];
